  q(EKG,'Which rhythm shows an irregularly irregular pattern with no clear P waves?','Atrial fibrillation',['Normal sinus rhythm','Sinus bradycardia','First-degree block'],'B','Atrial fibrillation raises the risk of stroke from blood clots.',NHA)
